SELECT wp.wp_type, ws.ws_sold_date_sk, SUM(ws.ws_net_profit) AS total_net_profit, SUM(wr.wr_return_amt) AS total_return_amount FROM web_sales ws JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk JOIN web_returns wr ON wr.wr_order_number = ws.ws_order_number WHERE ws.ws_sold_date_sk BETWEEN 2451754 AND 2451540 AND wp.wp_type = 'order                                             ' GROUP BY wp.wp_type, ws.ws_sold_date_sk
